svg.script:
(() => {
  const svg = document.documentElement;
  const crank = document.getElementById("crank-assembly");
  const beam = document.getElementById("walking-beam-group");
  let pitman = document.getElementById("pitman-arm");
  const rod = document.getElementById("polished-rod");
  const pins = [
    document.getElementById("beam-pivot"),
    document.getElementById("beam-pin"),
    document.getElementById("crank-pin"),
    document.getElementById("crank-center"),
    document.getElementById("polished-rod-pin")
  ];

  if (!crank || !beam || !pitman || !rod || pins.some((pin) => !pin)) return;

  const [beamPivotNode, beamPinNode, crankPinNode, crankCenterNode, polishedRodPinNode] = pins;
  const point = (node) => ({
    x: node.cx.baseVal.value,
    y: node.cy.baseVal.value
  });
  const transformedPoint = (node) => {
    const p = point(node);
    const transform = node.transform.baseVal.consolidate();
    if (!transform) return p;
    const m = transform.matrix;
    return {
      x: m.a * p.x + m.c * p.y + m.e,
      y: m.b * p.x + m.d * p.y + m.f
    };
  };
  const rotatePoint = (p, center, angle) => {
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    const x = p.x - center.x;
    const y = p.y - center.y;
    return {
      x: center.x + x * cos - y * sin,
      y: center.y + x * sin + y * cos
    };
  };
  const normalizeAngle = (angle) => {
    while (angle > Math.PI) angle -= Math.PI * 2;
    while (angle < -Math.PI) angle += Math.PI * 2;
    return angle;
  };
  const degrees = (angle) => angle * 180 / Math.PI;

  const beamPivot = point(beamPivotNode);
  // In the edited source, beam-pin is already stored at its visible position
  // for the beam's initial 21.598285 degree pose. Recover the pin's true local
  // angle instead of rotating that visible position a second time.
  const beamPinStart = point(beamPinNode);
  const crankCenter = point(crankCenterNode);
  const crankPinStart = transformedPoint(crankPinNode);
  const beamTransformStart = 21.598285 * Math.PI / 180;
  const beamStartAngle = Math.atan2(
    beamPinStart.y - beamPivot.y,
    beamPinStart.x - beamPivot.x
  );
  const beamBaseAngle = beamStartAngle - beamTransformStart;
  const beamRadius = Math.hypot(
    beamPinStart.x - beamPivot.x,
    beamPinStart.y - beamPivot.y
  );
  const pitmanLength = Math.hypot(
    crankPinStart.x - beamPinStart.x,
    crankPinStart.y - beamPinStart.y
  );
  const pitmanWidth = 13.972582;
  const hiddenTop = 13;
  const cycleDuration = 8;
  let previousBeamAngle = beamStartAngle;

  const originalCrankTransform = crank.getAttribute("transform") || "";

  if (pitman.tagName.toLowerCase() !== "path") {
    const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
    for (const attribute of Array.from(pitman.attributes)) {
      if (!["x", "y", "width", "height", "transform"].includes(attribute.name)) {
        path.setAttribute(attribute.name, attribute.value);
      }
    }
    pitman.replaceWith(path);
    pitman = path;
  }

  const cable = document.createElementNS("http://www.w3.org/2000/svg", "path");
  cable.setAttribute("id", "polished-rod-cable");
  cable.setAttribute("fill", "none");
  cable.setAttribute("stroke", "var(--pump-jack-stroke)");
  cable.setAttribute("stroke-width", "2.97386");
  cable.setAttribute("stroke-linecap", "round");
  cable.setAttribute("stroke-linejoin", "round");
  rod.parentNode.insertBefore(cable, rod);
  rod.setAttribute("display", "none");

  function solveBeam(crankPin) {
    const dx = crankPin.x - beamPivot.x;
    const dy = crankPin.y - beamPivot.y;
    const distance = Math.hypot(dx, dy);
    const direction = Math.atan2(dy, dx);
    const rawCosine = (
      beamRadius * beamRadius + distance * distance - pitmanLength * pitmanLength
    ) / (2 * beamRadius * distance);
    const spread = Math.acos(Math.max(-1, Math.min(1, rawCosine)));
    const candidates = [direction - spread, direction + spread];
    const angle = candidates.reduce((best, candidate) => {
      const bestGap = Math.abs(normalizeAngle(best - previousBeamAngle));
      const gap = Math.abs(normalizeAngle(candidate - previousBeamAngle));
      return gap < bestGap ? candidate : best;
    });
    previousBeamAngle = angle;
    return {
      angle,
      pin: {
        x: beamPivot.x + beamRadius * Math.cos(angle),
        y: beamPivot.y + beamRadius * Math.sin(angle)
      }
    };
  }

  function drawPitman(topPin, bottomPin) {
    const dx = bottomPin.x - topPin.x;
    const dy = bottomPin.y - topPin.y;
    const length = Math.hypot(dx, dy);
    const ux = dx / length;
    const uy = dy / length;
    const nx = -uy * pitmanWidth / 2;
    const ny = ux * pitmanWidth / 2;
    const top = {
      x: topPin.x - ux * hiddenTop,
      y: topPin.y - uy * hiddenTop
    };
    pitman.setAttribute("d",
      `M ${top.x + nx} ${top.y + ny} L ${top.x - nx} ${top.y - ny} `
      + `L ${bottomPin.x - nx} ${bottomPin.y - ny} `
      + `L ${bottomPin.x + nx} ${bottomPin.y + ny} Z`
    );
  }

  function drawRod(beamAngle) {
    const beamTransformAngle = beamAngle - beamBaseAngle;
    const lowAngle = -28.5 * Math.PI / 180;
    const highAngle = 22.1 * Math.PI / 180;
    const range = highAngle - lowAngle;
    const raised = Math.max(0, Math.min(1,
      (beamTransformAngle - lowAngle) / range
    ));

    // Keep only a short, thin vertical cable. Its lower end stays fixed while
    // the upper end follows the horse-head motion without moving sideways.
    const rodX = 78.2;
    const fixedLineBottom = 381.45;
    const cableTop = 189.0 - raised * 28.0;

    cable.setAttribute("d", `M ${rodX} ${cableTop} V ${fixedLineBottom}`);
    setPinPosition(polishedRodPinNode, { x: rodX, y: cableTop });
  }

  function setPinPosition(node, p) {
    node.removeAttribute("transform");
    node.setAttribute("cx", p.x);
    node.setAttribute("cy", p.y);
  }

  function render(phase) {
    const crankPin = rotatePoint(crankPinStart, crankCenter, phase);
    const solved = solveBeam(crankPin);
    const beamTransformAngle = solved.angle - beamBaseAngle;

    crank.setAttribute(
      "transform",
      `rotate(${degrees(phase)} ${crankCenter.x} ${crankCenter.y}) ${originalCrankTransform}`
    );
    beam.setAttribute(
      "transform",
      `rotate(${degrees(beamTransformAngle)} ${beamPivot.x} ${beamPivot.y})`
    );
    drawPitman(solved.pin, crankPin);
    drawRod(solved.angle);
    setPinPosition(beamPinNode, solved.pin);
    setPinPosition(crankPinNode, crankPin);
  }

  render(0);

  let startTime = null;
  function animate(timestamp) {
    if (startTime === null) startTime = timestamp;
    const elapsed = (timestamp - startTime) / 1000;
    render((elapsed / cycleDuration) * Math.PI * 2);
    svg.__pumpjackAnimationFrame = requestAnimationFrame(animate);
  }
  svg.__pumpjackAnimationFrame = requestAnimationFrame(animate);
})();
